use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut prios: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        let n: int = parts.len() as int
        if n == 0 {
            println("error")
        } else if parts[0] == "add" && n == 3 {
            match parts[2].parse::<int>() {
                Ok(p) => {
                    let mut pos: int = names.len() as int
                    let mut i: int = 0
                    while i < names.len() as int {
                        if prios[i as usize] < p {
                            pos = i
                            break
                        }
                        i += 1
                    }
                    names.insert(pos as usize, parts[1])
                    prios.insert(pos as usize, p)
                }
                Err(_) => println("error"),
            }
        } else if parts[0] == "pop" && n == 1 {
            if names.len() == 0 {
                println("empty")
            } else {
                println("${names[0]}")
                names.remove(0)
                prios.remove(0)
            }
        } else if parts[0] == "peek" && n == 1 {
            if names.len() == 0 {
                println("empty")
            } else {
                println("${names[0]}")
            }
        } else if parts[0] == "size" && n == 1 {
            println("${names.len()}")
        } else {
            println("error")
        }
    }
    println("left:")
    let mut i: int = 0
    while i < names.len() as int {
        println("${names[i as usize]} ${prios[i as usize]}")
        i += 1
    }
}

